sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var STAGING_TABLE = 'x_2226556_server_0_canopi_stg';
    var stagingSysId = '';

    try {
        var bodyStr = request.body.dataString;

        // -------------------------------------------------------
        // STEP 1 – Insert the raw payload into the staging table
        // -------------------------------------------------------
        var gr = new GlideRecord(STAGING_TABLE);
        gr.initialize();
        gr.setValue('payload', bodyStr || '');
        gr.setValue('source_system', 'CANOPI');
        stagingSysId = gr.insert();

        if (!stagingSysId) {
            response.setStatus(500);
            response.setBody({
                status: 'error',
                message: 'Failed to create staging record'
            });
            return;
        }

        // Re-open the record so we can update it after validation
        var stg = new GlideRecord(STAGING_TABLE);
        stg.get(stagingSysId);

        // -------------------------------------------------------
        // STEP 2 – Validate payload is not empty & structure
        // -------------------------------------------------------
        if (!bodyStr) {
            stg.setValue('state', 'failed');
            stg.setValue('error_message', 'Payload is empty');
            stg.setValue('http_response_code', '400');
            stg.update();

            response.setStatus(400);
            response.setBody({
                status: 'failed',
                staging_sys_id: String(stagingSysId),
                message: 'Payload is empty'
            });
            return;
        }

        var payload;
        try {
            payload = JSON.parse(bodyStr);
        } catch (parseErr) {
            stg.setValue('state', 'failed');
            stg.setValue('error_message', 'Payload is not valid JSON: ' + parseErr);
            stg.setValue('http_response_code', '400');
            stg.update();

            response.setStatus(400);
            response.setBody({
                status: 'failed',
                staging_sys_id: String(stagingSysId),
                message: 'Payload is not valid JSON'
            });
            return;
        }

        // Validate top-level structure
        var structureErrors = [];
        var expectedTopKeys = ['sourceSystem', 'serialNumber', 'hostName', 'dnsDomain', 'orderId', 'action', 'device', 'location', 'support'];
        for (var i = 0; i < expectedTopKeys.length; i++) {
            if (!payload.hasOwnProperty(expectedTopKeys[i])) {
                structureErrors.push('Missing top-level field: ' + expectedTopKeys[i]);
            }
        }

        if (payload.device && typeof payload.device !== 'object') {
            structureErrors.push('Field "device" must be an object');
        }
        if (payload.location && typeof payload.location !== 'object') {
            structureErrors.push('Field "location" must be an object');
        }
        if (payload.support && typeof payload.support !== 'object') {
            structureErrors.push('Field "support" must be an object');
        }

        if (structureErrors.length > 0) {
            stg.setValue('state', 'failed');
            stg.setValue('error_message', 'Payload structure errors: ' + structureErrors.join('; '));
            stg.setValue('http_response_code', '400');
            stg.update();

            response.setStatus(400);
            response.setBody({
                status: 'failed',
                staging_sys_id: String(stagingSysId),
                message: 'Payload structure validation failed',
                errors: structureErrors
            });
            return;
        }

        // Populate staging fields from payload
        stg.setValue('source_system', payload.sourceSystem || '');
        stg.setValue('external_id', payload.orderId || '');
        stg.setValue('action', String(payload.action || '').toLowerCase());
        stg.setValue('correlation_id', payload.orderId || '');

        // -------------------------------------------------------
        // STEP 3 – Validate critical fields: managedBy, selfSupport, clli
        // -------------------------------------------------------
        var criticalEmpty = [];
        var support = payload.support || {};
        var location = payload.location || {};

        if (!support.managedBy || String(support.managedBy).trim() === '') {
            criticalEmpty.push('support.managedBy');
        }
        if (!support.selfSupport || String(support.selfSupport).trim() === '') {
            criticalEmpty.push('support.selfSupport');
        }
        if (!location.clli || String(location.clli).trim() === '') {
            criticalEmpty.push('location.clli');
        }

        if (criticalEmpty.length > 0) {
            stg.setValue('state', 'failed');
            stg.setValue('error_message', 'Critical fields are empty: ' + criticalEmpty.join(', '));
            stg.setValue('http_response_code', '400');
            stg.update();

            response.setStatus(400);
            response.setBody({
                status: 'failed',
                staging_sys_id: String(stagingSysId),
                message: 'Critical field validation failed. The following fields are empty',
                empty_fields: criticalEmpty
            });
            return;
        }

        // -------------------------------------------------------
        // STEP 4 – Validate required fields are not empty
        // -------------------------------------------------------
        var device = payload.device || {};
        var missingFields = [];

        if (!payload.sourceSystem || String(payload.sourceSystem).trim() === '') {
            missingFields.push('sourceSystem');
        }
        if (!payload.hostName || String(payload.hostName).trim() === '') {
            missingFields.push('hostName');
        }
        if (!payload.dnsDomain || String(payload.dnsDomain).trim() === '') {
            missingFields.push('dnsDomain');
        }
        if (device.slot === undefined || device.slot === null || String(device.slot).trim() === '') {
            missingFields.push('device.slot');
        }
        if (!location.room || String(location.room).trim() === '') {
            missingFields.push('location.room');
        }
        if (!location.grid || String(location.grid).trim() === '') {
            missingFields.push('location.grid');
        }
        if (location.floor === undefined || location.floor === null || String(location.floor).trim() === '') {
            missingFields.push('location.floor');
        }
        if (!support.primarySA || String(support.primarySA).trim() === '') {
            missingFields.push('support.primarySA');
        }
        if (!support.backUpSA || String(support.backUpSA).trim() === '') {
            missingFields.push('support.backUpSA');
        }
        if (!support.SupportGroup || String(support.SupportGroup).trim() === '') {
            missingFields.push('support.SupportGroup');
        }

        if (missingFields.length > 0) {
            stg.setValue('state', 'failed');
            stg.setValue('error_message', 'Required fields are missing or empty: ' + missingFields.join(', '));
            stg.setValue('http_response_code', '400');
            stg.update();

            response.setStatus(400);
            response.setBody({
                status: 'failed',
                staging_sys_id: String(stagingSysId),
                message: 'Required field validation failed. The following field values are missing',
                missing_fields: missingFields
            });
            return;
        }

        // -------------------------------------------------------
        // STEP 5 – All validations passed
        // -------------------------------------------------------
        stg.setValue('state', 'pending');
        stg.setValue('http_response_code', '202');
        stg.setValue('response_message', 'Request acknowledged. Server ingestion status will be rolled back.');
        stg.update();

        response.setStatus(202);
        response.setBody({
            status: 'acknowledged',
            staging_sys_id: String(stagingSysId),
            message: 'Request acknowledged. We will rollback the response of server ingestion status.'
        });

    } catch (e) {
        gs.error('CANOPI ingest handler error: ' + e);

        // Update staging record to failed if it was created
        if (stagingSysId) {
            var errGr = new GlideRecord(STAGING_TABLE);
            if (errGr.get(stagingSysId)) {
                errGr.setValue('state', 'failed');
                errGr.setValue('error_message', 'Unexpected error: ' + e);
                errGr.setValue('http_response_code', '500');
                errGr.update();
            }
        }

        response.setStatus(500);
        response.setBody({
            status: 'error',
            staging_sys_id: stagingSysId ? String(stagingSysId) : '',
            message: 'Internal server error during payload ingestion'
        });
    }
})(request, response);
